-- School: synthetic sample data for the dhimantAI "Ask your data" lab.
-- Generated by scripts/datalab/generate_seeds.py. Do not edit by hand.
-- Every name and number is invented. No real person, shop, school or clinic.

CREATE TABLE classes (
  class_id integer PRIMARY KEY,
  grade integer NOT NULL,
  section text NOT NULL,
  class_teacher text NOT NULL
);
COMMENT ON TABLE classes IS 'One row per class section.';
COMMENT ON COLUMN classes.class_id IS 'Class number.';
COMMENT ON COLUMN classes.grade IS 'Grade (8, 9 or 10).';
COMMENT ON COLUMN classes.section IS 'Section letter.';
COMMENT ON COLUMN classes.class_teacher IS 'Class teacher (invented name).';

CREATE TABLE students (
  student_id integer PRIMARY KEY,
  student_name text NOT NULL,
  class_id integer NOT NULL REFERENCES classes,
  gender text NOT NULL,
  joined_on date NOT NULL
);
COMMENT ON TABLE students IS 'One row per student. Names are invented.';
COMMENT ON COLUMN students.student_id IS 'Student number.';
COMMENT ON COLUMN students.student_name IS 'Invented name with initial.';
COMMENT ON COLUMN students.class_id IS 'Class (see classes).';
COMMENT ON COLUMN students.gender IS 'F or M, as recorded at admission.';
COMMENT ON COLUMN students.joined_on IS 'Date the student joined. Some joined after the year began.';

CREATE TABLE attendance (
  student_id integer NOT NULL REFERENCES students,
  month date NOT NULL,
  school_days integer NOT NULL,
  days_present integer NOT NULL,
  PRIMARY KEY (student_id, month)
);
COMMENT ON TABLE attendance IS 'One row per student per month, only for months after the student joined.';
COMMENT ON COLUMN attendance.student_id IS 'Student (see students).';
COMMENT ON COLUMN attendance.month IS 'First day of the month.';
COMMENT ON COLUMN attendance.school_days IS 'Days the school was open that month for this student.';
COMMENT ON COLUMN attendance.days_present IS 'Days the student was present. Compare students with days_present / school_days, not raw counts.';

CREATE TABLE exams (
  exam_id integer PRIMARY KEY,
  exam_name text NOT NULL,
  held_on date NOT NULL,
  max_marks integer NOT NULL
);
COMMENT ON TABLE exams IS 'One row per exam.';
COMMENT ON COLUMN exams.exam_id IS 'Exam number.';
COMMENT ON COLUMN exams.exam_name IS 'Exam name.';
COMMENT ON COLUMN exams.held_on IS 'First day of the exam.';
COMMENT ON COLUMN exams.max_marks IS 'Marks each paper is out of. The unit test is out of 25, the others out of 100.';

CREATE TABLE marks (
  student_id integer NOT NULL REFERENCES students,
  exam_id integer NOT NULL REFERENCES exams,
  subject text NOT NULL,
  marks integer,
  PRIMARY KEY (student_id, exam_id, subject)
);
COMMENT ON TABLE marks IS 'One row per student, exam and subject.';
COMMENT ON COLUMN marks.student_id IS 'Student (see students).';
COMMENT ON COLUMN marks.exam_id IS 'Exam (see exams).';
COMMENT ON COLUMN marks.subject IS 'English, Maths or Science.';
COMMENT ON COLUMN marks.marks IS 'Marks scored. Blank (NULL) when the student was absent for that paper; blank is not zero.';
